async function run() {
  for (const page of pages) {
    const { error } = await supabase.from('marketing_pages').upsert(page, { onConflict: 'id' });
    if (error) throw error;
  }
  for (const block of blocks) {
    const { error } = await supabase.from('marketing_content_blocks').upsert(block, { onConflict: 'id' });
    if (error) throw error;
  }
  console.log('Seeded', pages.length, 'pages and', blocks.length, 'content blocks.');
}

run();
